<script setup>
import { ref, onMounted, onUnmounted } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import http from '../../api/http'

const documents = ref([])
const chunks = ref([])
const chunksVisible = ref(false)
const loading = ref(false)
let pollTimer = null

onMounted(() => loadDocs())
onUnmounted(() => {
  if (pollTimer) { clearInterval(pollTimer); pollTimer = null }
})

async function loadDocs() {
  loading.value = true
  try {
    const data = await http.get('/admin/documents')
    documents.value = data || []
    startPolling()
  } catch {}
  finally { loading.value = false }
}

/** 濡傛灉鏈?PROCESSING 鐘舵€佺殑鏂囨。锛屾瘡 3 绉掕嚜鍔ㄥ埛鏂?*/
function startPolling() {
  if (pollTimer) { clearInterval(pollTimer); pollTimer = null }
  const hasProcessing = documents.value.some(d => d.status === 'PROCESSING')
  if (hasProcessing) {
    pollTimer = setInterval(async () => {
      try {
        const data = await http.get('/admin/documents')
        documents.value = data || []
        if (!documents.value.some(d => d.status === 'PROCESSING')) {
          clearInterval(pollTimer)
          pollTimer = null
        }
      } catch { /* 杞闈欓粯澶辫触 */ }
    }, 3000)
  }
}

function statusType(s) {
  if (s === 'DONE') return 'success'
  if (s === 'PROCESSING') return 'warning'
  if (s === 'FAILED') return 'danger'
  return 'info'
}

function formatSize(bytes) {
  if (!bytes) return '0B'
  if (bytes < 1024) return bytes + 'B'
  return (bytes / 1024).toFixed(1) + 'KB'
}

async function viewChunks(docId) {
  try {
    const data = await http.get(`/document/${docId}/chunks`)
    chunks.value = data || []
    chunksVisible.value = true
  } catch {}
}

async function reprocess(docId) {
  try {
    await http.post(`/admin/document/${docId}/reprocess`)
    ElMessage.success('宸叉彁浜ら噸鏂拌В鏋?)
    loadDocs()
  } catch {}
}

async function remove(docId) {
  try {
    await ElMessageBox.confirm('纭畾鍒犻櫎璇ユ枃妗ｏ紵', '璀﹀憡', { type: 'warning' })
    await http.delete(`/admin/document/${docId}`)
    ElMessage.success('宸插垹闄?)
    loadDocs()
  } catch {}
}
</script>

